export function formatHours(hours: number | null): string {
  if (hours == null || isNaN(hours)) return 'N/A';
  const wholeHours = Math.floor(hours);
  const minutes = Math.round((hours - wholeHours) * 60);
  return `${wholeHours}h ${minutes}m`;
}

export function formatHoursDuration(hours: number | null): string {
  if (hours == null || isNaN(hours)) return 'N/A';
  if (hours < 1.0 / 60.0) {
    const totalSeconds = hours * 60.0 * 60.0;
    const wholeSeconds = Math.floor(totalSeconds);
    const remainingMillis = Math.round((totalSeconds - wholeSeconds) * 1000);
    return `${wholeSeconds}s ${remainingMillis}ms`;
  } else if (hours < 1.0) {
    const totalMinutes = hours * 60.0;
    const wholeMinutes = Math.floor(totalMinutes);
    const remaningSeconds = Math.round((totalMinutes - wholeMinutes) * 60.0);
    return `${wholeMinutes}m ${remaningSeconds}s`;
  } else if (hours < 48.0) {
    const wholeHours = Math.floor(hours);
    const minutes = Math.round((hours - wholeHours) * 60.0);
    return `${wholeHours}h ${minutes}m`;
  } else {
    const totalDays = hours / 24.0;
    const wholeDays = Math.floor(totalDays);
    const remainingHours = Math.round((totalDays - wholeDays) * 24.0);
    return `${wholeDays}d ${remainingHours}h`;
  }
}
